<script lang="ts">
  import { get } from 'svelte/store';
  import { tick } from 'svelte';
  import { fly, fade } from 'svelte/transition';
  import { prefersReducedMotion } from 'svelte/motion';
  import Icon from './Icon.svelte';
  import SheetChangeReview from './SheetChangeReview.svelte';
  import MesaTable from './MesaTable.svelte';
  import { room, masterAssets, desktopAvailable, rememberedRoom, hostRoom, joinRoom, reconnectRoom, openRoomCard, importRoomCover, sendRoom, leaveRoom, loadMasterAssets, importRoomAsset, createRoomScene, saveRoomThreat, saveRoomDocument, deleteRoomDocument, saveRoomMap, showRoomMap, type RoomMap, type RoomThreat, type RoomDocument, type LocalCharacter, type RoomCard, type RoomCharacter } from '../mesa';

  let { characters, rooms, onOpen, onNew, onDeleteRoom, onRoomsChanged, onSettings, confirmLeave }: {
    characters: LocalCharacter[];
    rooms: RoomCard[];
    onOpen: (sheet: RoomCharacter) => void;
    onNew: () => void;
    onDeleteRoom: (item:RoomCard) => void | Promise<void>;
    onRoomsChanged: () => void;
    onSettings: () => void;
    confirmLeave: boolean;
  } = $props();
  let roomName=$state(''),address=$state(''),port=$state(''),code=$state(''),displayName=$state('');
  let selectedLocal=$state(''),selectedParticipant=$state(''),busy=$state(false),error=$state('');
  let view=$state<'home'|'join'|'create'|'config'|'table'>(get(room).status==='idle'?'home':'table');
  let configured=$state<RoomCard|null>(null),configuredName=$state('');
  let configTab=$state<'geral'|'jogadores'|'preparacao'|'ameacas'|'recursos'>('geral');
  let configDialog=$state<HTMLDivElement|undefined>(undefined);
  let configReturnFocus:HTMLElement|null=null;
  let imageName=$state(''),sceneName=$state(''),artName=$state(''),editingMap=$state<RoomMap|null>(null),loadingAssets=$state(false),openingSavedPlayer=$state(false);
  const newThreat=():RoomThreat=>({name:'',nd:'1/4',kind:'',size:'Médio',role:'minion',initiative:0,perception:0,defense:10,fortitude:0,reflex:0,will:0,maxHp:1,maxMp:0,movement:9,attackName:'',attackFormula:'',damageFormula:'',actions:'',immunities:'',resistances:'',equipment:'',treasure:'',notes:''});
  let threatDraft=$state<RoomThreat>(newThreat());
  const newDocument=():RoomDocument=>({kind:'note',title:'',body:'',visibility:'private'});
  let documentDraft=$state<RoomDocument>(newDocument());
  $effect(()=>{if(view==='config')configDialog?.focus();});
  $effect(()=>{if(openingSavedPlayer&&$room.status==='ready')openingSavedPlayer=false;else if(openingSavedPlayer&&$room.status==='offline'){openingSavedPlayer=false;view='join';error='Não foi possível reconectar. Confira os dados salvos abaixo.';}});

  async function create(id?:string,name?:string){busy=true;error='';try{await hostRoom(name||roomName,id);view='table';onRoomsChanged();}catch(e){error=String(e);}busy=false;}
  function join(){try{error='';joinRoom(address,Number(port),code,displayName);view='table';}catch(e){error=String(e);}}
  function openRecent(item:RoomCard){error='';if(item.role==='master'){void openConfig(item);return;}if(item.connection){address=item.connection.address;port=String(item.connection.port);code=item.connection.code;displayName=item.connection.name;}try{openingSavedPlayer=true;openRoomCard(item);view='table';}catch(e){openingSavedPlayer=false;error=String(e);view='join';}}
  async function openConfig(item:RoomCard){if(item.role!=='master'||$room.status!=='idle'&&$room.role!=='master')return;configReturnFocus=document.activeElement as HTMLElement;configured=item;configuredName=item.name;configTab='geral';view='config';error='';loadingAssets=true;try{await loadMasterAssets(item.id);}catch(e){error=String(e);}loadingAssets=false;}
  async function closeConfig(){view=$room.role==='master'&&$room.status==='ready'?'table':'home';editingMap=null;await tick();if(configReturnFocus?.isConnected)configReturnFocus.focus();}
  function tableConfig(){if($room.role==='master'&&$room.room){const item=rooms.find(r=>r.id===$room.room?.id);if(item)void openConfig(item);}}
  async function chooseCover(){if(!configured)return;try{configured=await importRoomCover(configured.id);onRoomsChanged();}catch(e){if(!String(e).includes('cancelada'))error=String(e);}}
  async function importImage(kind:'map'|'token'){if(!configured)return;try{await importRoomAsset(configured.id,kind,kind==='map'?imageName:artName);if(kind==='map')imageName='';else artName='';}catch(e){if(!String(e).includes('cancelada'))error=String(e);}}
  async function addNarrativeScene(){if(!configured||!sceneName.trim())return;try{await createRoomScene(configured.id,sceneName);sceneName='';}catch(e){error=String(e);}}
  async function saveThreat(){if(!configured)return;error='';try{await saveRoomThreat(configured.id,threatDraft);threatDraft=newThreat();}catch(e){error=String(e);}}
  async function saveDocument(){if(!configured)return;error='';try{await saveRoomDocument(configured.id,documentDraft);documentDraft=newDocument();}catch(e){error=String(e);}}
  async function removeDocument(id:string,title:string){if(!configured||!confirm(`Apagar ${title}? Esta ação não pode ser desfeita.`))return;error='';try{await deleteRoomDocument(configured.id,id);if(documentDraft.id===id)documentDraft=newDocument();}catch(e){error=String(e);}}
  async function saveMap(){if(!configured||!editingMap)return;try{await saveRoomMap(configured.id,editingMap);editingMap=null;}catch(e){error=String(e);}}
  async function publishMap(id:string|null){if(!configured)return;try{await showRoomMap(configured.id,id);}catch(e){error=String(e);}}
  async function leave(){if(confirmLeave&&$room.status==='ready'&&!confirm('Sair da mesa agora?'))return;await leaveRoom();view='home';configured=null;onRoomsChanged();}
  function chosenCharacter(){return characters.find(c=>c.id===selectedLocal);}
  function assign(){const c=chosenCharacter();if(c&&selectedParticipant)sendRoom({type:'assign_sheet',participantId:selectedParticipant,data:c.data});}
</script>

<div class="mesa-view">
  {#if !desktopAvailable}<p class="mesa-notice">A Mesa usa o servidor embutido no EXE. Abra o aplicativo desktop para hospedar ou entrar.</p>{/if}
  {#if error}<p class="mesa-error" role="alert">{error}</p>{/if}
  {#if $room.message}<p class="mesa-notice" role="status">{$room.message}</p>{/if}

  {#if view==='home' || view==='create' || view==='join' || (view==='config'&&$room.status==='idle')}
    <div class="mesa-library" inert={view==='config'}>
      <div class="mesa-library-actions"><button class="primary" onclick={()=>view=view==='create'?'home':'create'}><Icon name="plus"/>Criar mesa</button><button onclick={()=>view=view==='join'?'home':'join'}><Icon name="link"/>Entrar com convite</button>{#if rememberedRoom()}<button class="mesa-subtle" onclick={()=>{reconnectRoom();view='table';}}>Reconectar</button>{/if}</div>
      {#if view==='create'}<section class="mesa-card mesa-inline-form"><div><h2>Criar mesa</h2><p>Abra uma campanha para jogadores na mesma rede ou VPN.</p></div><label>Nome da mesa<input bind:value={roomName} maxlength="80" placeholder="Ex.: Jornada em Arton"/></label><button class="primary" disabled={!desktopAvailable||busy||!roomName.trim()} onclick={()=>create()}>Abrir mesa</button></section>{/if}
      {#if view==='join'}<section class="mesa-card mesa-inline-form"><div><h2>Entrar na mesa</h2><p>Use os dados enviados pelo mestre.</p></div><label>IP do mestre<input bind:value={address} placeholder="192.168.1.10"/></label><label>Porta<input type="number" min="1" max="65535" bind:value={port}/></label><label>Código<input bind:value={code} autocomplete="off"/></label><label>Seu nome<input bind:value={displayName} maxlength="60"/></label><button class="primary" disabled={!desktopAvailable} onclick={join}>Entrar</button></section>{/if}
      {#if rooms.length}<div class="room-card-grid">{#each rooms as item}<article class="room-card"><button class="room-card-main" onclick={()=>openRecent(item)}>{#if item.coverUrl}<img src={item.coverUrl} alt=""/>{:else}<span class="room-cover-fallback"><Icon name="map" size={28}/><strong>{item.name.slice(0,2).toUpperCase()}</strong></span>{/if}<span class="room-card-info"><strong>{item.name}</strong><small>{item.role==='master'?'Mestre':'Jogador'} · {item.lastOpenedAt?new Date(item.lastOpenedAt*1000).toLocaleDateString('pt-BR'):'Ainda não aberta'}</small></span></button><footer>{#if item.role==='master'}<button onclick={()=>openConfig(item)}><Icon name="settings" size={15}/>Configurar</button><button class="icon-button mesa-danger" aria-label={`Apagar mesa ${item.name}`} title="Apagar mesa" onclick={()=>onDeleteRoom(item)}><Icon name="trash" size={15}/></button>{:else}<span>Conexão salva neste dispositivo</span>{/if}</footer></article>{/each}</div>{:else if view==='home'}<div class="empty-state"><Icon name="map" size={34}/><strong>Nenhuma mesa recente</strong><span>Crie uma campanha ou entre com um convite.</span></div>{/if}
    </div>
  {:else if view==='table' || (view==='config'&&$room.role==='master'&&$room.status==='ready')}
    <div inert={view==='config'}><MesaTable {characters} {onOpen} {onNew} onConfig={tableConfig} {onSettings} onLeave={leave}/></div>
  {/if}

  {#if view==='config'}
    <button class="mesa-config-backdrop" in:fade={{duration:150}} out:fade={{duration:120}} aria-label="Fechar Área do mestre" onclick={closeConfig}></button>
    <div class="mesa-config-overlay" in:fly={{y:prefersReducedMotion.current?0:8,duration:prefersReducedMotion.current?120:200}} out:fly={{y:prefersReducedMotion.current?0:8,duration:prefersReducedMotion.current?120:140}} role="dialog" aria-modal="true" aria-label="Área do mestre" tabindex="-1" bind:this={configDialog} onkeydown={e=>{if(e.key==='Escape')closeConfig();}}>
      <div class="mesa-session-head"><div><button onclick={closeConfig}>← Voltar</button><small>ÁREA DO MESTRE</small><h2>{configuredName}</h2></div><div class="mesa-session-actions"><button aria-label="Configurações do aplicativo" title="Configurações do aplicativo" onclick={onSettings}><Icon name="settings" size={16}/></button>{#if $room.role==='master'&&$room.status==='ready'}<button class="primary" onclick={closeConfig}>Voltar à mesa</button>{:else}<button class="primary" disabled={busy||!desktopAvailable||!configuredName.trim()} onclick={()=>create(configured?.id,configuredName)}>Abrir mesa</button>{/if}</div></div>
      <nav class="mesa-master-tabs" aria-label="Área do mestre"><button class:active={configTab==='geral'} onclick={()=>configTab='geral'}>Hoje</button><button class:active={configTab==='preparacao'} onclick={()=>configTab='preparacao'}>Cenas</button><button class:active={configTab==='ameacas'} onclick={()=>configTab='ameacas'}>Ameaças</button><button class:active={configTab==='recursos'} onclick={()=>configTab='recursos'}>Conteúdo</button><button class:active={configTab==='jogadores'} onclick={()=>configTab='jogadores'}>Jogadores</button></nav>
      {#if error}<p class="mesa-error" role="alert">{error}</p>{/if}

      {#if configTab==='geral'}
        <div class="mesa-config-basics"><section class="mesa-card"><h3>Identidade</h3><div class="config-cover">{#if configured?.coverUrl}<img src={configured.coverUrl} alt="Capa de {configuredName}"/>{:else}<span class="room-cover-fallback"><Icon name="map" size={28}/><strong>{configuredName.slice(0,2).toUpperCase()}</strong></span>{/if}</div><button onclick={chooseCover}>Escolher capa</button><label>Nome da mesa<input bind:value={configuredName} maxlength="80" disabled={$room.role==='master'&&$room.status==='ready'}/></label><p>{$room.role==='master'&&$room.status==='ready'?'Feche a mesa para alterar o nome.':'O nome será salvo ao abrir a mesa.'}</p></section><section class="mesa-card"><h3>Acesso e convite</h3><p>Entrada por IP, porta e código, com aprovação individual do mestre.</p>{#if $room.invite}<div class="mesa-invite"><span>IP: <code>{$room.invite.address}</code></span><span>Porta: <code>{$room.invite.port}</code></span><span>Código: <code>{$room.invite.code}</code></span><small>Em VPN, use o IP da VPN se o endereço sugerido não funcionar.</small></div>{:else}<p>O convite será criado quando a mesa abrir.</p>{/if}</section></div>
      {:else if configTab==='jogadores'}
        <SheetChangeReview/>
        {#if $room.role==='master'&&$room.status==='ready'}<div class="mesa-columns"><div class="mesa-stack"><section class="mesa-card"><h3>Aprovações</h3>{#each $room.participants as person}<div class="mesa-person"><span>{person.name} {person.approved?'':'· aguardando'}</span><button class:mesa-danger={person.approved} onclick={()=>sendRoom({type:person.approved?'revoke':'approve',participantId:person.id})}>{person.approved?'Revogar':'Aprovar'}</button></div>{:else}<p>Nenhum jogador entrou ainda.</p>{/each}</section><section class="mesa-card"><h3>Fichas recebidas</h3>{#each $room.offers as offer}<div class="mesa-person"><span>{offer.participantName}: {offer.data.name}</span><button onclick={()=>sendRoom({type:'accept_sheet',participantId:offer.participantId})}>Aceitar ficha</button></div>{:else}<p>Nenhuma ficha aguardando.</p>{/each}</section><section class="mesa-card"><h3>Atribuir ficha</h3><div class="mesa-pair"><select bind:value={selectedParticipant}><option value="">Jogador</option>{#each $room.participants.filter(p=>p.approved) as p}<option value={p.id}>{p.name}</option>{/each}</select><select bind:value={selectedLocal}><option value="">Ficha local</option>{#each characters as c}<option value={c.id}>{c.name}</option>{/each}</select></div><button disabled={!selectedParticipant||!selectedLocal} onclick={assign}>Atribuir</button><button class="mesa-subtle" onclick={onNew}>Criar nova ficha</button></section></div><section class="mesa-card"><h3>Fichas na mesa</h3>{#each $room.characters as sheet}<div class="mesa-person"><span>{sheet.data.name} <small>rev. {sheet.revision}</small></span><button onclick={()=>{void closeConfig();onOpen(sheet);}}>Abrir ficha</button></div><label class="mesa-check"><input type="checkbox" checked={!!sheet.canEditProficiencies} onchange={e=>sendRoom({type:'set_proficiency_permission',sheetId:sheet.id,allowed:e.currentTarget.checked})}/> Permitir editar proficiências</label>{:else}<p>Nenhuma ficha atribuída ainda.</p>{/each}</section></div><button class="mesa-subtle" onclick={leave}>Encerrar mesa</button>{:else}<p class="mesa-notice">Abra a mesa para receber jogadores e atribuir fichas.</p>{/if}
      {:else if configTab==='preparacao'}
        <section class="mesa-card mesa-master-card"><h3>Cena narrativa</h3><p>Abra uma cena sem mapa nem grade para viagem, conversa ou investigação.</p><div class="mesa-pair"><input aria-label="Nome da cena narrativa" bind:value={sceneName} maxlength="80" placeholder="Ex.: Conselho da cidade"/><button disabled={!sceneName.trim()} onclick={addNarrativeScene}>+ Criar cena</button></div></section>
        <section class="mesa-card mesa-master-card"><h3>Cenas e mapas</h3><p>As cenas preparadas ficam privadas. Apenas a cena ativa aparece aos jogadores.</p><div class="mesa-pair"><input aria-label="Nome do novo mapa" bind:value={imageName} maxlength="80" placeholder="Nome opcional"/><button disabled={loadingAssets} onclick={()=>importImage('map')}>+ Enviar mapa tático</button></div>{#each $masterAssets.maps as map}<div class="mesa-map-row"><div><strong>{map.name}</strong><small>{map.kind==='narrative'?'Narrativa':`${map.width} × ${map.height} px · Tática`} {#if $masterAssets.activeMap?.id===map.id}· ativa{/if}</small></div><div><button onclick={()=>editingMap={...map}}>Ajustar</button><button class:primary={$masterAssets.activeMap?.id!==map.id} disabled={$masterAssets.activeMap?.id===map.id} onclick={()=>publishMap(map.id)}>{$masterAssets.activeMap?.id===map.id?'Publicada':'Mostrar na mesa'}</button></div></div>{:else}<p>Nenhuma cena preparada.</p>{/each}{#if $masterAssets.activeMap}<button class="mesa-subtle" onclick={()=>publishMap(null)}>Voltar à mesa vazia</button>{/if}</section>
        {#if editingMap}<section class="mesa-card mesa-master-card"><h3>Ajustar {editingMap.name}</h3><label>Nome<input bind:value={editingMap.name} maxlength="80"/></label>{#if editingMap.kind==='tactical'}<div class="mesa-pair"><label>Tamanho da célula (px)<input type="number" min="16" max="512" bind:value={editingMap.cellPx}/></label><label>Metros por célula<input type="number" min="0.1" max="100" step="0.1" bind:value={editingMap.metresPerCell}/></label></div><label class="mesa-check"><input type="checkbox" bind:checked={editingMap.gridVisible}/> Mostrar grade</label><label class="mesa-check"><input type="checkbox" bind:checked={editingMap.snap}/> Encaixar tokens na grade</label><fieldset class="mesa-backdrop-choice"><legend>Fundo ao redor do mapa</legend><label><input type="radio" name="backdrop" checked={!editingMap.backdropColor} onchange={()=>editingMap={...editingMap!,backdropColor:null}}/> Automático · cor predominante</label><label><input type="radio" name="backdrop" checked={!!editingMap.backdropColor} onchange={()=>editingMap={...editingMap!,backdropColor:'#667b8d'}}/> Escolher cor</label>{#if editingMap.backdropColor}<input type="color" aria-label="Cor manual do fundo" value={editingMap.backdropColor} onchange={e=>editingMap={...editingMap!,backdropColor:e.currentTarget.value}}/>{/if}</fieldset>{/if}<div class="mesa-token-actions"><button class="primary" onclick={saveMap}>Salvar ajustes</button><button onclick={()=>editingMap=null}>Cancelar</button></div></section>{/if}
        <div class="preparation-placeholders"><article><Icon name="sword" size={22}/><h3>Encontros</h3><p>Grupos de NPCs e ameaças prontos para entrar no mapa.</p><span>Em breve</span></article><article><Icon name="warning" size={22}/><h3>Perigos</h3><p>Armadilhas, ambientes hostis e desafios complexos.</p><span>Em breve</span></article><article><Icon name="book" size={22}/><h3>Handouts</h3><p>Textos e imagens para compartilhar durante a sessão.</p><span>Em breve</span></article></div>
      {:else if configTab==='ameacas'}
        <section class="mesa-card mesa-master-card"><h3>Ameaças preparadas</h3><p>A ficha base é reutilizada. Cada token colocado recebe PV e PM próprios; notas e tesouro ficam só com o mestre.</p>{#each $masterAssets.threats as threat}<div class="mesa-map-row"><div><strong>{threat.name}</strong><small>ND {threat.nd} · {threat.role==='minion'?'Lacaio':threat.role==='solo'?'Solo':'Especial'} · PV {threat.maxHp}</small></div><div><button onclick={()=>threatDraft={...threat}}>Editar</button><button disabled={$room.status!=='ready'||$room.role!=='master'||!$room.activeMap} onclick={()=>sendRoom({type:'place_token',threatId:threat.id,x:($room.activeMap?.width||0)/2,y:($room.activeMap?.height||0)/2})}>Colocar na cena</button></div></div>{:else}<p>Nenhuma ameaça preparada.</p>{/each}</section>
        <section class="mesa-card mesa-master-card"><h3>{threatDraft.id?'Editar ameaça':'Nova ameaça'}</h3><div class="mesa-threat-grid"><label>Nome<input bind:value={threatDraft.name} maxlength="80"/></label><label>ND<input bind:value={threatDraft.nd} maxlength="20"/></label><label>Tipo/subtipo<input bind:value={threatDraft.kind} maxlength="80"/></label><label>Tamanho<input bind:value={threatDraft.size} maxlength="40"/></label><label>Papel<select bind:value={threatDraft.role}><option value="minion">Lacaio</option><option value="solo">Solo</option><option value="special">Especial</option></select></label><label>Iniciativa<input type="number" bind:value={threatDraft.initiative}/></label><label>Percepção<input type="number" bind:value={threatDraft.perception}/></label><label>Defesa<input type="number" min="0" bind:value={threatDraft.defense}/></label><label>Fortitude<input type="number" bind:value={threatDraft.fortitude}/></label><label>Reflexos<input type="number" bind:value={threatDraft.reflex}/></label><label>Vontade<input type="number" bind:value={threatDraft.will}/></label><label>PV máximos<input type="number" min="1" bind:value={threatDraft.maxHp}/></label><label>PM máximos<input type="number" min="0" bind:value={threatDraft.maxMp}/></label><label>Deslocamento (m)<input type="number" min="0" bind:value={threatDraft.movement}/></label><label>Nome do ataque<input bind:value={threatDraft.attackName} maxlength="80"/></label><label>Teste de ataque<input bind:value={threatDraft.attackFormula} maxlength="30" placeholder="1d20+5"/></label><label>Dano<input bind:value={threatDraft.damageFormula} maxlength="30" placeholder="1d8+2"/></label></div><div class="mesa-threat-notes"><label>Ações e habilidades<textarea bind:value={threatDraft.actions} maxlength="4000"></textarea></label><label>Imunidades<textarea bind:value={threatDraft.immunities} maxlength="1000"></textarea></label><label>Resistências e RD<textarea bind:value={threatDraft.resistances} maxlength="1000"></textarea></label><label>Equipamento<textarea bind:value={threatDraft.equipment} maxlength="1000"></textarea></label><label>Tesouro privado<textarea bind:value={threatDraft.treasure} maxlength="1000"></textarea></label><label>Notas táticas privadas<textarea bind:value={threatDraft.notes} maxlength="4000"></textarea></label></div><div class="mesa-token-actions"><button class="primary" disabled={!threatDraft.name.trim()||!threatDraft.nd.trim()} onclick={saveThreat}>Salvar ameaça</button><button onclick={()=>threatDraft=newThreat()}>Nova ficha</button></div></section>
      {:else}
        <section class="mesa-card mesa-master-card"><h3>Notas e handouts</h3><p>Notas privadas ajudam a preparar a sessão. Handouts podem ser mostrados aos jogadores durante a mesa.</p>
          {#each $masterAssets.documents as document}<div class="mesa-map-row"><div><strong>{document.title}</strong><small>{document.kind==='handout'?'Handout':document.kind==='npc'?'NPC':'Nota'} · {document.visibility==='public'?'Público':'Privado'}</small></div><div><button onclick={()=>documentDraft={...document}}>Editar</button>{#if document.kind==='handout'}<button disabled={$room.status!=='ready'||$room.role!=='master'} onclick={()=>sendRoom({type:'show_handout',id:document.id})}>Mostrar</button>{/if}<button class="mesa-danger" onclick={()=>document.id&&removeDocument(document.id,document.title)}>Apagar</button></div></div>{:else}<p>Nenhum conteúdo preparado.</p>{/each}
        </section>
        <section class="mesa-card mesa-master-card"><h3>{documentDraft.id?'Editar conteúdo':'Novo conteúdo'}</h3><div class="mesa-threat-grid"><label>Tipo<select bind:value={documentDraft.kind}><option value="note">Nota</option><option value="npc">NPC</option><option value="handout">Handout</option></select></label><label>Visibilidade<select bind:value={documentDraft.visibility}><option value="private">Só mestre</option><option value="public">Todos</option></select></label><label>Título<input bind:value={documentDraft.title} maxlength="80"/></label></div><label>Texto<textarea bind:value={documentDraft.body} maxlength="20000"></textarea></label><div class="mesa-token-actions"><button class="primary" disabled={!documentDraft.title.trim()} onclick={saveDocument}>Salvar</button><button onclick={()=>documentDraft=newDocument()}>Novo</button></div></section>
        <section class="mesa-card mesa-master-card"><h3>Tokens, artes e mídia</h3><p>Envie imagens para tokens avulsos ou para ilustrar fichas. Artes e músicas já adicionadas continuam disponíveis na mesa.</p><div class="mesa-pair"><input aria-label="Nome do novo token" bind:value={artName} maxlength="80" placeholder="Nome opcional"/><button disabled={loadingAssets} onclick={()=>importImage('token')}>+ Enviar token</button></div>{#each $masterAssets.tokenArt as art}<div class="mesa-map-row"><div><strong>{art.name}</strong><small>{art.width} × {art.height} px</small></div><span>Disponível na mesa</span></div>{:else}<p>Nenhuma imagem enviada.</p>{/each}</section>{/if}
    </div>
  {/if}
</div>
